def letter(char):
    """A Ukrainian letter the board's font lacks, as 8 rows; None if none."""
    at = LETTER_KEYS.find(char)
    return LETTER_DATA[at * 8:at * 8 + 8] if at >= 0 else None


def icon(name):
    """An icon by name, as 16 rows of two bytes; None if none."""
    try:
        at = ICON_NAMES.index(name)
    except ValueError:
        return None
    return ICON_DATA[at * 32:at * 32 + 32]


def look(char):
    """The board's Latin letter that looks like this one, or the letter."""
    at = LOOK_FROM.find(char)
    return LOOK_TO[at] if at >= 0 else char
